          >
            {loading ? "Creation..." : "C'est parti !"}
          </button>
        </form>

        <p className="text-sm text-text-muted text-center mt-6">
          Deja inscrit ?{" "}
          <Link href="/login" className="text-accent font-semibold">
            Se connecter
          </Link>
        </p>
      </div>
    </div>
  );
}

