() => {
  // Find the pill-shaped nav container with border
  const ul = document.querySelector('nav ul') || document.querySelector('nav ol') || document.querySelector('nav');
  const ulParent = ul ? ul.parentElement : null;

  // Walk up ancestors looking for a border/rounded element
  let el = ul;
  const ancestors = [];
  while (el && el !== document.body) {
    const s = getComputedStyle(el);
    if (s.borderRadius !== '0px' || s.border !== '0px none rgb(32, 32, 32)' || s.boxShadow !== 'none') {
      ancestors.push({
        tag: el.tagName,
        borderRadius: s.borderRadius,
        border: s.border,
        boxShadow: s.boxShadow,
        bg: s.backgroundColor,
        width: el.offsetWidth,
        height: el.offsetHeight,
        padding: s.padding
      });
    }
    el = el.parentElement;
  }

  // Also get the list items inside nav
  const lis = document.querySelectorAll('nav li');
